// schon fertig fuer dich
function umschalten(l, i){ l[i].erledigt = !l[i].erledigt; }
function offeneAnzahl(l){ var n=0; for(var i=0;i<l.length;i++){ if(!l[i].erledigt) n++; } return n; }

// schon fertig: zeichnet die App und macht sie klickbar
function zeichne(){
  var html = '<input id="feld" placeholder="Neue Aufgabe" style="padding:6px;font-size:15px"> <button id="add" style="padding:6px 12px;cursor:pointer">Hinzufuegen</button>';
  html += '<div style="margin:8px 0;color:#555">Offen: ' + offeneAnzahl(liste) + '</div>';
  html += '<ul style="list-style:none;padding:0;font:16px sans-serif">';
  for(var i=0;i<liste.length;i++){
    var a = liste[i];
    var stil = a.erledigt ? 'text-decoration:line-through;color:#999' : '';
    html += '<li data-i="'+i+'" style="cursor:pointer;padding:5px;'+stil+'">' + (a.erledigt ? '[x] ' : '[ ] ') + a.text + '</li>';
  }
  html += '</ul>';
  document.body.innerHTML = html;
  document.getElementById('add').onclick = function(){
    var f = document.getElementById('feld');
    if(f.value.trim() !== ''){ hinzufuegen(liste, f.value.trim()); zeichne(); }
  };
  var items = document.querySelectorAll('li');
  for(var k=0;k<items.length;k++){
    items[k].onclick = function(){ umschalten(liste, parseInt(this.getAttribute('data-i'), 10)); zeichne(); };
  }
}
