            {
              id: "matheanfassen-master-quiz",
              type: "quiz",
              title: "Quiz: Meister der Funktionen",
              questions: [
                { q: "Welche Funktion zeichnet eine Parabel (eine Schale mit tiefstem Punkt)?", options: ["sin(x)", "x*x", "2*x+1"], answer: 1, why: "x*x ist die Parabel. sin(x) ist die Welle, 2*x+1 die Gerade." },
                { q: "Bei y = m·x + b: was ist b?", options: ["Die Steigung", "Der Achsenabschnitt, wo die Gerade die senkrechte Achse trifft", "Die Nullstelle"], answer: 1, why: "b ist der Achsenabschnitt (Wert bei x=0). m ist die Steigung." },
                { q: "Welche Familie wird immer steiler und beschreibt Zinseszins?", options: ["Die Gerade", "Das exponentielle Wachstum (z. B. 2^x)", "Die Welle"], answer: 1, why: "Exponentielles Wachstum wie 2^x wird immer steiler, das ist die Zinseszins-Form." },
                { q: "Woran erkennst du am Graphen die Lösung von f(x) = 0?", options: ["Am höchsten Punkt", "An den Nullstellen, wo die Kurve die x-Achse trifft", "Am linken Rand"], answer: 1, why: "Die Nullstellen (die grünen Punkte) sind die Lösungen von f(x)=0." }
              ]
            }
