            cwd: "/home/lernender",
            modes: { "/home/lernender/backup.sh": "644" },
            intro: "1. cat backup.sh   2. chmod 755 backup.sh   3. ./backup.sh   4. cat backup/app.log",
            ziel: s => s.exists("/home/lernender/backup/app.log") && s.ran(/^\.\/backup\.sh$/) && s.ran(/^cat\s+backup\/app\.log$/)
