const serverFoundationTrack = CURRICULUM.tracks.find(track => track.id === "srv");
if (!serverFoundationTrack) throw new Error("Server-Lernpfad 'srv' fehlt.");
Object.entries(SERVER_FOUNDATION_EXTENSION).forEach(([stageId, lessons]) => {
  const stage = serverFoundationTrack.stages.find(item => item.id === stageId);
  if (!stage) throw new Error("Server-Stufe '" + stageId + "' fehlt.");
  const quizIndex = stage.lessons.findIndex(lesson => lesson.type === "quiz");
  stage.lessons.splice(quizIndex < 0 ? stage.lessons.length : quizIndex, 0, ...lessons);
});

/* Fachliche Korrekturen an historischen Zahlungslektionen. */
const paymentStage = serverFoundationTrack.stages.find(stage => stage.id === "srv-6");
const checkoutLesson = paymentStage.lessons.find(lesson => lesson.id === "srv-6-1");
checkoutLesson.beats = [
  { kind: "text", html: "<p><b>Stripe Checkout</b> hostet die Bezahloberfläche und hält Kartendaten aus deinem eigenen Frontend heraus. Das reduziert deinen PCI-DSS-Prüfumfang erheblich, beseitigt die Verantwortung aber nicht vollständig: PCI-Sicherheit ist eine <b>gemeinsame Verantwortung</b>, und dein Unternehmen muss die für seine Integration erforderlichen Schritte weiterhin erfüllen.</p>" },
  { kind: "predict", frage: "<p>Was ist der größte Sicherheitsvorteil von gehostetem Checkout?</p>", optionen: ["Kartendaten laufen nicht durch dein eigenes Frontend und der PCI-Prüfumfang wird kleiner", "Alle übrigen Sicherheitsmaßnahmen werden dadurch unwichtig", "Geheime Schlüssel dürfen dadurch in den Browser"], answer: 0, enthuellung: "<p>Richtig. Die gehostete Zahlungsseite reduziert Risiko und Umfang. Verkäufer, Integration und Kontosicherheit bleiben trotzdem verantwortlich.</p>" },
  { kind: "text", html: "<p>Deine Seite erstellt nur über den eigenen Server eine Checkout Session und leitet dorthin weiter. Karten- oder Bankdaten werden direkt beim Zahlungsanbieter eingegeben. Verwende ausschließlich HTTPS, minimale Schlüsselrechte und die offiziell vorgesehene Integration.</p>" }
];

const paymentIdempotencyLesson = paymentStage.lessons.find(lesson => lesson.id === "srv-6-5");
paymentIdempotencyLesson.title = "Doppelte Nachrichten sicher beherrschen";
paymentIdempotencyLesson.beats = [
  { kind: "text", html: "<p>Netzwerke wiederholen Nachrichten. Ein Webhook kann zweimal eintreffen, zwei Worker können gleichzeitig starten und ein Client kann nach einem Timeout erneut senden. <b>Idempotent</b> bedeutet: Dieselbe fachliche Nachricht mehrfach zu verarbeiten hat dieselbe Wirkung wie einmal.</p>" },
  { kind: "predict", frage: "<p>Derselbe bezahlte Checkout wird zweimal geliefert. Was soll passieren?</p>", optionen: ["Zwei Bestellungen und zwei Freischaltungen", "Die bereits verarbeitete Geschäfts-ID wird erkannt; der Zustand bleibt einmal bezahlt", "Der Nutzer wird gesperrt"], answer: 1, enthuellung: "<p>Genau. Eine eindeutige Datenbankregel und eine Transaktion verhindern Doppelwirkung auch bei gleichzeitiger Verarbeitung.</p>" },
  { kind: "text", html: "<p>Nutze den Idempotency Key bei geeigneten ausgehenden Anfragen und eine eindeutige Checkout-, Payment- oder Event-Referenz bei eingehenden Ereignissen. Markiere nicht erst nach der Freischaltung lose „irgendwo“ das Event, sondern führe Statuswechsel und Berechtigung konsistent aus.</p>" }
];

const paymentQuiz = paymentStage.lessons.find(lesson => lesson.id === "srv-6-quiz");
paymentQuiz.questions = [
  { q: "Was ist der Sicherheitsvorteil einer gehosteten Bezahlseite?", options: ["Kartendaten laufen nicht durch das eigene Frontend und der PCI-Prüfumfang wird kleiner", "Der Verkäufer hat keinerlei Sicherheitsverantwortung mehr", "Secret Keys dürfen öffentlich werden", "Webhooks sind überflüssig"], answer: 0, why: "Hosted Checkout reduziert Risiko und PCI-Umfang deutlich. PCI-DSS und Kontosicherheit bleiben eine gemeinsame Verantwortung." },
  { q: "Welcher Schlüssel darf ausdrücklich im Browser verwendet werden?", options: ["Der Secret Key", "Der Publishable Key", "Das Webhook Signing Secret", "Der Datenbank-Service-Key"], answer: 1, why: "Publishable Keys sind für öffentliche Client-Integrationen gedacht. Secret- und Webhook-Schlüssel bleiben serverseitig." },
  { q: "Warum wird der erlaubte Price auf dem Server ausgewählt?", options: ["Weil der Browser manipulierbar ist", "Weil Preise nie angezeigt werden dürfen", "Weil JSON nicht rechnen kann", "Nur wegen der Schriftart"], answer: 0, why: "Der Client darf einen Wunsch senden, aber der Server entscheidet über Produkt, Betrag und Währung." },
  { q: "Was ist die belastbare Grundlage einer Pro-Freischaltung?", options: ["Die Erfolgs-URL", "Ein signiertes, passendes Serverereignis und eine dauerhaft gespeicherte Berechtigung", "localStorage allein", "Ein Screenshot"], answer: 1, why: "Browserzustand ist manipulierbar und gerätegebunden. Freischaltung erfolgt serverseitig und idempotent." },
  { q: "Warum muss ein Webhook idempotent verarbeitet werden?", options: ["Ereignisse können doppelt oder gleichzeitig eintreffen", "Damit CSS lädt", "Damit Rechnungen kürzer werden", "Weil Test und Live identisch sind"], answer: 0, why: "Eindeutige Geschäfts-IDs und Transaktionen verhindern doppelte Lieferung bei Wiederholungen." },
  { q: "Erzeugt jede erfolgreiche einmalige Zahlung automatisch eine rechtlich passende Rechnung?", options: ["Ja, ohne Konfiguration", "Nein; Rechnungserstellung, Pflichtangaben und Steuerbehandlung müssen passend eingerichtet werden", "Nur wenn der Browser offen bleibt", "Testzahlungen immer"], answer: 1, why: "Zahlungsbestätigung und Rechnung sind verschiedene Dinge; der Verkäufer bleibt für die korrekte Abrechnung verantwortlich." }
];

const apiStage = serverFoundationTrack.stages.find(stage => stage.id === "srv-5");
const apiStatusLesson = apiStage.lessons.find(lesson => lesson.id === "srv-5-2");
const authPrediction = apiStatusLesson.beats.find(beat => beat.kind === "predict" && String(beat.frage).includes("401"));
if (authPrediction) {
  authPrediction.optionen = ["Nicht oder nicht mehr gültig authentifiziert", "Ressource nicht gefunden", "Serverfehler"];
  authPrediction.answer = 0;
  authPrediction.enthuellung = "<p>Genau. 401 verlangt eine gültige Authentifizierung. Ist die Identität bekannt, aber die Aktion verboten, ist 403 die präzisere Antwort.</p>";
}

/* Mathe-Klarstellung: Vorzeichen des y-Werts ist nicht Steigungsrichtung. */
const touchMathTrack = CURRICULUM.tracks.find(track => track.id === "matheanfassen");
if (!touchMathTrack) throw new Error("Mathe-Lernpfad 'matheanfassen' fehlt.");
const linearStage = touchMathTrack.stages.find(stage => stage.id === "matheanfassen-0");
const slopeLesson = linearStage.lessons.find(lesson => lesson.id === "matheanfassen-0-3");
const clarificationBeat = {
  kind: "predict",
  frage: "<p>Bei <code>y = 2x</code> liegt der Punkt für <code>x = -3</code> bei <code>y = -6</code>. Fällt die Gerade deshalb?</p>",
  optionen: ["Ja, ein negativer y-Wert bedeutet fallend", "Nein. Von links nach rechts werden die y-Werte größer; die Gerade steigt trotz negativer Werte auf der linken Seite", "Nur die x-Achse entscheidet"],
  answer: 1,
  enthuellung: "<p>Genau. <b>Negativ</b> beschreibt hier die Lage unter der x-Achse. <b>Steigend</b> beschreibt die Veränderung von links nach rechts. Bei positivem <code>m</code> gilt für <code>x₂ &gt; x₁</code> immer <code>y₂ &gt; y₁</code>.</p>"
};
const existingClarification = slopeLesson.beats.some(beat => String(beat.frage || "").includes("Fällt die Gerade deshalb"));
if (!existingClarification) {
  const plotIndex = slopeLesson.beats.findIndex(beat => beat.kind === "plot");
  slopeLesson.beats.splice(plotIndex < 0 ? slopeLesson.beats.length : plotIndex + 1, 0, clarificationBeat);
}

const seoTrack = CURRICULUM.tracks.find(track => track.id === "seo");
if (!seoTrack) throw new Error("SEO-Lernpfad 'seo' fehlt.");
Object.entries(SEO_FOUNDATION_EXTENSION).forEach(([stageId, lessons]) => {
  const stage = seoTrack.stages.find(item => item.id === stageId);
  if (!stage) throw new Error("SEO-Stufe '" + stageId + "' fehlt.");
  stage.lessons.push(...lessons);
});

